<?php

declare(strict_types=1);

namespace App\Infrastructure\Persistence\Sqlite;

use App\Domain\Entity\ShippingMethod;
use App\Domain\Port\Outbound\ShippingMethodRepositoryPort;
use PDO;

/**
 * Driven SQLite Adapter generated by Tuzygent Hexagonal Harness
 */
final readonly class SqliteShippingMethodRepository implements ShippingMethodRepositoryPort
{
    public function __construct(
        private PDO $pdo
    ) {
        $this->pdo->exec('
            CREATE TABLE IF NOT EXISTS shipping_methods (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                code TEXT NOT NULL,
                is_active INTEGER NOT NULL DEFAULT 1,
                created_at TEXT NOT NULL
            )
        ');
    }

    public function findAll(): array
    {
        $stmt = $this->pdo->query('SELECT * FROM shipping_methods ORDER BY id DESC');
        $rows = $stmt ? $stmt->fetchAll() : [];
        return array_map(fn(array $r) => new ShippingMethod(
            id: (int) $r['id'],
            name: (string) $r['name'],
            code: (string) $r['code'],
            isActive: (bool) ((int) $r['is_active']),
            createdAt: (string) $r['created_at']
        ), $rows);
    }

    public function findById(int $id): ?ShippingMethod
    {
        $stmt = $this->pdo->prepare('SELECT * FROM shipping_methods WHERE id = ? LIMIT 1');
        $stmt->execute([$id]);
        $r = $stmt->fetch();
        if (!$r) {
            return null;
        }
        return new ShippingMethod(
            id: (int) $r['id'],
            name: (string) $r['name'],
            code: (string) $r['code'],
            isActive: (bool) ((int) $r['is_active']),
            createdAt: (string) $r['created_at']
        );
    }

    public function save(ShippingMethod $entity): int
    {
        $now = date('Y-m-d H:i:s');
        if ($entity->id === null) {
            $stmt = $this->pdo->prepare('INSERT INTO shipping_methods (name, code, is_active, created_at) VALUES (?, ?, ?, ?)');
            $stmt->execute([$entity->name, $entity->code, $entity->isActive ? 1 : 0, $now]);
            return (int) $this->pdo->lastInsertId();
        }
        $stmt = $this->pdo->prepare('UPDATE shipping_methods SET name = ?, code = ?, is_active = ? WHERE id = ?');
        $stmt->execute([$entity->name, $entity->code, $entity->isActive ? 1 : 0, $entity->id]);
        return $entity->id;
    }

    public function delete(int $id): void
    {
        $stmt = $this->pdo->prepare('DELETE FROM shipping_methods WHERE id = ?');
        $stmt->execute([$id]);
    }
}
